private theorem sum_arc (g : Arc → K) :
    ∑ e, g e =
      g st1 + g st2 + g su + g ut3 + g uv + g vt1 + g vw + g wt2 + g wt3

private theorem excessTerm_mono {S T : Finset ι} (hST : S ⊆ T)
    (t : Fin m) (i : ι) :
    I.excessTerm S t i ≤ I.excessTerm T t i

theorem optimalUCost_le (I : FlowInstance ℝ) {S : Finset Terminal}
    (hS : I.Admissible S) :
    I.optimalUCost ≤ I.ucost S

theorem le_optimalUCost (I : FlowInstance ℝ) {r : ℝ}
    (h : ∀ S : Finset Terminal, I.Admissible S → r ≤ I.ucost S) :
    r ≤ I.optimalUCost

private theorem sum_split (S : Finset ι) (g : ι → ℝ) :
    (∑ i, g i) =
      S.sum g + Sᶜ.sum g

theorem optimalRoutingCost_le {S : Finset (Fin k)} {R : I.Routing}
    (hR : I.Admissible S R) :
    I.optimalRoutingCost ≤ I.routingCost S

private theorem den_lt_two_num_of_half_lt (q : ℚ)
    (hlo : (1 : ℝ) / 2 < (q : ℝ)) :
    (q.den : ℤ) < 2 * q.num

theorem load_eq (hd : J.d = I.d) {r : Terminal → List Arc}
    (hr : IsRouting r) (a : Arc) :
    J.load r a = I.load (routingSet r) a

theorem ucost_eq (hd : J.d = I.d) (hc : J.c = I.c) {r : Terminal → List Arc}
    (hr : IsRouting r) :
    J.ucost r = I.ucost (routingSet r)

private theorem gate_min_check :
    ∀ l0 ∈ gatePaths 0, ∀ l1 ∈ gatePaths 1, ∀ l2 ∈ gatePaths 2,
      GateAdmissible ![l0, l1, l2] → 100 ≤ gateCost ![l0, l1, l2]

theorem append {a b c : V} {l₁ l₂ : List A}
    (h₁ : IsWalk src dst a b l₁) (h₂ : IsWalk src dst b c l₂) :
    IsWalk src dst a c (l₁ ++ l₂)

theorem append_inv {a b : V} {l₁ l₂ : List A}
    (h : IsWalk src dst a b (l₁ ++ l₂)) :
    ∃ c, IsWalk src dst a c l₁ ∧ IsWalk src dst c b l₂

theorem rank_add_length_le {rank : V → ℕ}
    (hrank : ∀ e, rank (src e) < rank (dst e)) {a b : V} {l : List A}
    (h : IsWalk src dst a b l) : rank a + l.length ≤ rank b

theorem eq_nil_of_self {rank : V → ℕ}
    (hrank : ∀ e, rank (src e) < rank (dst e)) {a : V} {l : List A}
    (h : IsWalk src dst a a l) : l = []

theorem exists_prefix_of_mem_vertexTrace {a b v : V} {l : List A}
    (h : IsWalk src dst a b l) (hv : v ∈ vertexTrace dst a l) :
    ∃ l₁ l₂, l = l₁ ++ l₂ ∧ IsWalk src dst a v l₁

theorem exists_prefix_cons_of_mem {a b : V} {l : List A} {e : A}
    (h : IsWalk src dst a b l) (he : e ∈ l) :
    ∃ q r, l = q ++ e :: r ∧ IsWalk src dst a (src e) q

theorem prefix_unique {rank : V → ℕ}
    (hrank : ∀ e, rank (src e) < rank (dst e)) {a v : V}
    {q₁ s₁ q₂ s₂ : List A} (hq : q₁ ++ s₁ = q₂ ++ s₂)
    (hw₁ : IsWalk src dst a v q₁) (hw₂ : IsWalk src dst a v q₂) : q₁ = q₂

@[ext]
theorem PathUnionVertex.ext {Z : ι → List A}
    {u v : PathUnionVertex src dst sV Z} (h : u.1 = v.1) : u = v

theorem optimalRoutingCost_le (I : Instance ι m) {S : Finset ι}
    (hS : I.Admissible S) :
    I.optimalRoutingCost ≤ I.routingCost S

theorem add_div_add_le_max_div {U₁ U₂ F₁ F₂ : ℝ}
    (hF₁ : 0 < F₁) (hF₂ : 0 < F₂) :
    (U₁ + U₂) / (F₁ + F₂) ≤ max (U₁ / F₁) (U₂ / F₂)
